def transform(grid):
    h, w = len(grid), len(grid[0])

    # Locate the solid divider.
    col = next((c for c in range(w)
                if all(grid[r][c] == grid[0][c] for r in range(h))), None)
    row = next((r for r in range(h)
                if len(set(grid[r])) == 1), None)

    if col is not None:
        template = [line[:col] for line in grid]
        other = [line[col + 1:] for line in grid]
        fill = max({v for line in other for v in line},
                   key=lambda v: sum(line.count(v) for line in other))
    else:
        template = grid[:row]
        other = grid[row + 1:]
        # In the horizontal arrangement, the sparse template color is
        # also the background color used in the output.
        fill = None

    counts = {}
    for line in template:
        for v in line:
            counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)
    mark = min((v for v in counts if v != background),
               key=lambda v: counts[v])

    if fill is None:
        fill = mark

    return [[3 if v == mark else fill for v in line] for line in template]
