def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the solid divider.
    divider = None
    for c in range(w):
        if len({grid[r][c] for r in range(h)}) == 1:
            divider = ("v", c)
            break
    if divider is None:
        for r in range(h):
            if len(set(grid[r])) == 1:
                divider = ("h", r)
                break

    if divider[0] == "v":
        k = divider[1]
        panels = [[row[:k] for row in grid],
                  [row[k + 1:] for row in grid]]
    else:
        k = divider[1]
        panels = [grid[:k], grid[k + 1:]]

    def frequencies(panel):
        counts = {}
        for row in panel:
            for value in row:
                counts[value] = counts.get(value, 0) + 1
        return counts

    first_counts = frequencies(panels[0])
    # Use the first panel when it contains a pattern; otherwise use the second.
    selected = 0 if len(first_counts) > 1 else 1
    counts = frequencies(panels[selected])
    background = max(counts, key=counts.get)
    mark = min((v for v in counts if v != background), key=lambda v: counts[v])

    if selected == 0:
        other_counts = frequencies(panels[1])
        output_background = max(other_counts, key=other_counts.get)
    else:
        output_background = background

    return [[3 if value == mark else output_background for value in row]
            for row in panels[selected]]
