def transform(grid):
    h, w = len(grid), len(grid[0])

    # Split at the solid divider.
    split_col = next(
        (c for c in range(w)
         if len({grid[r][c] for r in range(h)}) == 1),
        None
    )
    if split_col is not None:
        a = [row[:split_col] for row in grid]
        b = [row[split_col + 1:] for row in grid]
    else:
        split_row = next(r for r in range(h) if len(set(grid[r])) == 1)
        a, b = grid[:split_row], grid[split_row + 1:]

    ca = {v for row in a for v in row}
    cb = {v for row in b for v in row}
    common = ca & cb
    color = min(common, key=lambda v: sum(row.count(v) for row in a)
                                      + sum(row.count(v) for row in b))

    return [
        [3 if a[r][c] == color and b[r][c] == color else color
         for c in range(len(a[0]))]
        for r in range(len(a))
    ]
